{
  "passageId": "audio-perceptual-coding",
  "items": [
    {
      "slot": 1,
      "stem": "윗글의 내용에 대한 이해로 적절하지 않은 것은?",
      "stemPolarity": "SELECT_INCORRECT",
      "choices": [
        {
          "number": 1,
          "text": "축음기는 소리로 발생한 나팔의 진동에 따라 바늘이 판에 홈을 만드는 방식으로 소리를 저장한다."
        },
        {
          "number": 2,
          "text": "하나의 파일에 담긴 오디오 신호에서는 모든 소리 크기에 동일한 개수의 비트가 할당된다."
        },
        {
          "number": 3,
          "text": "각 소리 크기에 할당되는 비트의 개수가 늘어날수록 소리는 아날로그 원음에서 멀어진다."
        },
        {
          "number": 4,
          "text": "오디오 파일은 데이터 양이 많으므로 저장 공간을 절약하고 전송이 가능하도록 신호를 압축할 필요가 있다."
        },
        {
          "number": 5,
          "text": "지각부호화는 청각 특성에 따라 감도가 낮은 소리를 제거하는 방식으로 오디오 신호를 압축한다."
        }
      ],
      "answer": 3
    },
    {
      "slot": 2,
      "stem": "윗글을 바탕으로 이해한 내용으로 적절한 것은?",
      "stemPolarity": "SELECT_CORRECT",
      "choices": [
        {
          "number": 1,
          "text": "초기 녹음기는 소리를 아날로그 형태로 저장했지만 그 이후에 등장한 매체에서는 곧바로 디지털 형태로 기록하였다."
        },
        {
          "number": 2,
          "text": "각 소리 크기에 16비트를 할당할 때에는 소리 크기가 달라도 동일한 16자리의 이진수 값으로 나타낸다."
        },
        {
          "number": 3,
          "text": "조용할 때 청각이 감지할 수 있는 소리 크기의 최솟값은 소리의 주파수와 관계없이 동일하게 정해져 있다."
        },
        {
          "number": 4,
          "text": "소리 크기와 차폐 문턱값의 차이가 큰 소리일수록 해당 소리 크기에 더 많은 비트를 할당하여 소리의 손실을 낮춘다."
        },
        {
          "number": 5,
          "text": "지각부호화에서는 소리 크기에 따라 오디오 신호를 여러 임계대역으로 나누고 각 대역에서 차폐 문턱값을 구한다."
        }
      ],
      "answer": 4
    },
    {
      "slot": 3,
      "stem": "차폐에 대한 이해로 적절한 것은?",
      "stemPolarity": "SELECT_CORRECT",
      "choices": [
        {
          "number": 1,
          "text": "차폐음은 큰 소리로 인해 작은 소리가 들리지 않을 때 들리지 않게 된 작은 소리를 가리킨다."
        },
        {
          "number": 2,
          "text": "임계대역은 차폐음의 주파수를 기준으로 차폐가 가능한 최저 주파수와 최고 주파수 사이의 구간을 가리킨다."
        },
        {
          "number": 3,
          "text": "두 소리 사이에 차폐가 일어나는 정도는 두 소리의 주파수가 서로 멀어질수록 더 쉽게 일어나는 양상을 보인다."
        },
        {
          "number": 4,
          "text": "차폐가 일어날 수 있는 임계대역의 폭은 차폐음이 고음일 때가 저음일 때보다 더 좁게 나타난다."
        },
        {
          "number": 5,
          "text": "차폐 문턱값은 차폐를 고려할 때 실제 청각이 감지할 수 있는 소리 크기의 최댓값을 가리킨다."
        }
      ],
      "answer": 2
    }
  ]
}

